package com.yeyamo_mobile.api.gamification_service.infrastructure.web;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class})ResponseEntity<Map<String,Object>>bad(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now(),"status",400,"code","INVALID_OPERATION","message",e.getMessage()));}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<Map<String,Object>>missing(NoSuchElementException e){return ResponseEntity.status(404).body(Map.of("timestamp",Instant.now(),"status",404,"code","RESOURCE_NOT_FOUND","message",e.getMessage()));}}
